import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { Textarea } from "@/registry/erbium/ui/textarea";

export function TextareaButton() {
  return (
    <div className="grid w-full gap-related">
      <Textarea placeholder="Type your message here." />
      <Button>Send message</Button>
    </div>
  );
}

import { Textarea } from "@/registry/erbium/ui/textarea";

export default function TextareaDemo() {
  return <Textarea placeholder="Type your message here." />;
}

import { Textarea } from "@/registry/erbium/ui/textarea";

export default function TextareaDisabled() {
  return <Textarea placeholder="Type your message here." disabled />;
}

import { Field, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Textarea } from "@/registry/erbium/ui/textarea";

export function TextareaField() {
  return (
    <Field>
      <FieldLabel>Message</FieldLabel>
      <FieldDescription>Enter your message below.</FieldDescription>
      <Textarea placeholder="Type your message here." />
    </Field>
  );
}

